package com.farika.soundflow;
import android.app.*;import android.os.*;import android.content.*;import android.webkit.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
/** Visible first-party account operations. Never renders audio for the native player. */
public class AccountWebActivity extends Activity {
 private WebView web;private TextView status;private final Handler h=new Handler(Looper.getMainLooper());private String observed="",client="",authUsed="",key="",owner="";private boolean running=false,attempted=false,finished=false;private long started;private boolean pageReady=false,currentClient=false,checkingChallenge=false;private String challengeKey="";private long challengeStarted;private int requests;private String last="NOT_STARTED";
 private boolean origin(){if(web==null)return false;try{java.net.URI u=new java.net.URI(web.getUrl());return "https".equals(u.getScheme())&&("soundcloud.com".equals(u.getHost())||"www.soundcloud.com".equals(u.getHost())||"m.soundcloud.com".equals(u.getHost()))&&u.getRawUserInfo()==null&&(u.getPort()==-1||u.getPort()==443);}catch(Exception e){return false;}}
 private Button button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setTextColor(0xffb5f36d);b.setOnClickListener(v->r.run());return b;}
 @Override public void onCreate(Bundle state){super.onCreate(state);owner=getSharedPreferences("profile",0).getString("id","");client=Session.client(this);attempted=state!=null&&state.getBoolean("attempted");getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);getWindow().setStatusBarColor(0xff0e1016);getWindow().setNavigationBarColor(0xff0e1016);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(0xff0e1016);root.setPadding(12,8,12,8);if(Build.VERSION.SDK_INT>=35)root.setOnApplyWindowInsetsListener((v,i)->{android.graphics.Insets b=i.getInsets(WindowInsets.Type.systemBars());v.setPadding(b.left+12,b.top,b.right+12,b.bottom);return i;});setContentView(root);
 LinearLayout bar=new LinearLayout(this);bar.addView(button("Назад",this::finish),new LinearLayout.LayoutParams(0,-2,1));bar.addView(button("Обновить вход",()->{if(running){status.setText("Дождитесь результата текущего запроса перед обновлением входа.");return;}startActivityForResult(new Intent(this,LoginActivity.class),50);}),new LinearLayout.LayoutParams(0,-2,1));root.addView(bar);status=new TextView(this);status.setTextColor(0xfff5f6fa);status.setTextSize(15);status.setPadding(12,12,12,12);status.setText("Сохраняем через браузерную сессию SoundCloud. Плеер остаётся нативным. Если появится проверка, пройдите её здесь. Для повторной записи нажмите «Выполнить»; сама проверка изменение не сохраняет.");root.addView(status);
 try{web=new WebView(this);WebSettings s=web.getSettings();s.setUserAgentString(AccountBrowserProfile.desktop(s.getUserAgentString()));s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setMediaPlaybackRequiresUserGesture(true);CookieManager.getInstance().setAcceptCookie(true);CookieManager.getInstance().setAcceptThirdPartyCookies(web,true);web.setWebViewClient(websiteClient());observeWorkers();root.addView(web,new LinearLayout.LayoutParams(-1,0,1));web.loadUrl("https://soundcloud.com/you/likes");}catch(RuntimeException e){web=null;status.setText("Для операций аккаунта нужен Android System WebView. Установите или обновите его из доверенного магазина. Ваши загрузки не удалены.");root.addView(new TextView(this),new LinearLayout.LayoutParams(-1,0,1));}
 LinearLayout actions=new LinearLayout(this);actions.addView(button("Выполнить",this::confirm),new LinearLayout.LayoutParams(0,-2,1));actions.addView(button("Диагностика",()->new AlertDialog.Builder(this).setTitle("Операция аккаунта").setMessage("SoundFlow 1.0.0\n"+last+"\nFirst-party requests: "+requests+"\nНикакие значения токенов, cookie или паролей не показаны.").setPositiveButton("Закрыть",null).show()),new LinearLayout.LayoutParams(0,-2,1));root.addView(actions);if(attempted)status.setText("Предыдущая попытка могла завершиться на сайте. Сначала проверьте результат в SoundCloud. Автоматического повторного создания плейлиста нет.");
 }
 private void observe(WebResourceRequest r){String url=r.getUrl().toString();if(AuthCapture.api(url)){String a=AuthCapture.header(r.getRequestHeaders()),c=AuthCapture.client(url);h.post(()->{if(finished||isFinishing())return;requests++;if(!a.isEmpty())observed=a;if(!c.isEmpty()){client=c;currentClient=true;}maybeAuto();});}}
 private void observeWorkers(){ServiceWorkerController.getInstance().setServiceWorkerClient(new ServiceWorkerClient(){public WebResourceResponse shouldInterceptRequest(WebResourceRequest r){observe(r);return null;}});}
 protected WebViewClient websiteClient(){return new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView w,WebResourceRequest r){return r.isForMainFrame()&&!AuthCapture.site(r.getUrl().toString());}public WebResourceResponse shouldInterceptRequest(WebView w,WebResourceRequest r){observe(r);return null;}public void onPageFinished(WebView w,String url){pageReady=origin();if(pageReady)web.evaluateJavascript("(window.__sc_hydration||[]).filter(function(x){return x.hydratable==='apiClient';}).map(function(x){return x.data&&x.data.id;})[0]||''",raw->{try{Object value=new JSONTokener(raw).nextValue();if(value instanceof String&&((String)value).matches("[A-Za-z0-9_-]{16,256}")){client=(String)value;currentClient=true;}}catch(Exception ignored){}maybeAuto();});}public void onReceivedSslError(WebView w,SslErrorHandler handler,android.net.http.SslError e){handler.cancel();last="TLS_ERROR";status.setText("Ошибка сертификата. Запись остановлена.");}public void onReceivedError(WebView w,WebResourceRequest r,WebResourceError e){if(r.isForMainFrame()){last="PAGE_"+e.getErrorCode();status.setText("Сайт недоступен. Проверьте сеть и WebView. Сессия приложения не удалена.");}}};}
 private void maybeAuto(){if(pageReady&&currentClient&&!client.isEmpty()&&!running&&!attempted&&!finished&&getIntent().getBooleanExtra("auto",false))execute();}
 private void confirm(){if(running||finished||checkingChallenge)return;if(web==null||!origin()){status.setText("Дождитесь официальной страницы SoundCloud или обновите WebView.");return;}String op=getIntent().getStringExtra("op");String message="LIKE".equals(op)?"Поставить лайк в SoundCloud?":"UNLIKE".equals(op)?"Убрать лайк в SoundCloud?":"CREATE".equals(op)?"Создать приватный плейлист «"+getIntent().getStringExtra("title")+"»?":"Добавить трек в выбранный плейлист SoundCloud?";if(attempted)message+="\nПредыдущий результат неизвестен. Убедитесь, что изменение ещё не выполнено, чтобы не создать дубликат.";new AlertDialog.Builder(this).setTitle("Подтвердите изменение").setMessage(message).setNegativeButton("Отмена",null).setPositiveButton("Выполнить",(d,w)->execute()).show();}
 private String extra(String n){String s=getIntent().getStringExtra(n);return s==null?"":s;}
 private void execute(){if(checkingChallenge||!origin())return;if(owner.isEmpty()||!owner.equals(getSharedPreferences("profile",0).getString("id",""))){status.setText("Аккаунт изменился. Закройте эту операцию.");return;}if(!currentClient||client.isEmpty()){status.setText("Сайт ещё не предоставил конфигурацию API. Дождитесь загрузки или обновите вход.");return;}String cookieAuth=AuthCapture.cookie(CookieManager.getInstance().getCookie("https://soundcloud.com/"));authUsed=!observed.isEmpty()?observed:!cookieAuth.isEmpty()?cookieAuth:Session.get(this);key="_volna_"+UUID.randomUUID().toString().replace("-","");running=true;attempted=true;started=System.currentTimeMillis();last="PENDING";status.setText("Проверка аккаунта и выполнение запроса на сайте…");web.evaluateJavascript(AccountScript.build(key,authUsed,client,owner,extra("op"),extra("track"),extra("playlist"),extra("title")),null);h.postDelayed(poll,500);}
 private final Runnable poll=new Runnable(){public void run(){if(!running||finished||web==null)return;if(!origin()||System.currentTimeMillis()-started>60000){running=false;last="UNKNOWN_OUTCOME";status.setText("Результат неизвестен: страница сменилась или истёк срок ожидания. Проверьте изменение на сайте до повторной попытки. Сессия не удалена.");return;}web.evaluateJavascript("JSON.stringify(window["+AccountScript.quote(key)+"]||{})",raw->{try{Object decoded=new JSONTokener(raw).nextValue();JSONObject r=new JSONObject(String.valueOf(decoded));if(r.optBoolean("pending")||r.length()==0){h.postDelayed(poll,500);return;}running=false;int code=r.optInt("status");last=r.optBoolean("ok")?"SUCCESS_"+code:r.optString("reason")+"_"+code;if(r.optBoolean("ok")){if(!owner.equals(getSharedPreferences("profile",0).getString("id","")))return;if(!authUsed.isEmpty())Session.put(AccountWebActivity.this,authUsed,client);CookieManager.getInstance().flush();finished=true;Intent data=new Intent().putExtra("op",extra("op")).putExtra("track",extra("track")).putExtra("owner",owner).putExtra("playlist",r.optString("playlist_id"));setResult(RESULT_OK,data);finish();}else if(code==403&&AuthCapture.challenge(r.optString("challenge"))){beginChallenge(r.optString("challenge"));}else status.setText(code==401?"SoundCloud не принял сессию для этой операции (401). Обновите вход. Загрузки и данные не удалены.":code==403?"SoundCloud отклонил изменение (403). Сайт может требовать проверку или не разрешать запись. Пройдите проверку на видимой странице; повторяйте только после проверки результата.":"ACCOUNT_MISMATCH".equals(r.optString("reason"))?"На сайте открыт другой аккаунт. Изменение не выполнено. Обновите вход в нужный аккаунт.":"Операция не подтверждена: "+last+". Не считайте изменение сохранённым; проверьте результат на сайте.");}catch(Exception e){running=false;last="UNREADABLE_RESULT";status.setText("Не удалось подтвердить результат. Проверьте его на сайте; автоматического повтора нет.");}});}};
 private void beginChallenge(String url){if(!origin()||!AuthCapture.challenge(url))return;checkingChallenge=true;last="CHALLENGE_PENDING";challengeStarted=System.currentTimeMillis();challengeKey="_volna_check_"+UUID.randomUUID().toString().replace("-","");status.setText("SoundCloud запросил проверку. Пройдите её ниже. Проверка не означает, что лайк или плейлист уже сохранён.");web.evaluateJavascript(ChallengeScript.build(challengeKey,url),null);h.postDelayed(challengePoll,500);}
 private final Runnable challengePoll=new Runnable(){public void run(){if(!checkingChallenge||web==null||finished)return;if(!origin()||System.currentTimeMillis()-challengeStarted>180000){checkingChallenge=false;last="CHALLENGE_UNFINISHED";status.setText("Проверка не завершена. Изменение не подтверждено; автоматического повтора нет.");return;}web.evaluateJavascript("JSON.stringify(window["+AccountScript.quote(challengeKey)+"]||{})",raw->{try{Object value=new JSONTokener(raw).nextValue();JSONObject r=new JSONObject(String.valueOf(value));if(r.optBoolean("passed")){checkingChallenge=false;last="CHALLENGE_PASSED";CookieManager.getInstance().flush();status.setText("Проверка завершена. Нажмите «Выполнить», чтобы подтвердить повтор операции. До этого изменение не считается сохранённым.");return;}}catch(Exception ignored){}h.postDelayed(this,500);});}};
 @Override protected void onSaveInstanceState(Bundle b){b.putBoolean("attempted",attempted);super.onSaveInstanceState(b);}
 @Override protected void onActivityResult(int q,int r,Intent d){super.onActivityResult(q,r,d);if(q==50&&r==RESULT_OK){if(!owner.equals(getSharedPreferences("profile",0).getString("id",""))){status.setText("Подключён другой аккаунт. Закройте эту операцию и начните заново.");return;}observed="";currentClient=false;pageReady=false;if(web!=null)observeWorkers();if(web!=null)web.loadUrl("https://soundcloud.com/you/likes");status.setText("Вход обновлён. Проверьте, выполнена ли предыдущая операция, затем при необходимости нажмите «Выполнить».");}}
 @Override protected void onDestroy(){h.removeCallbacksAndMessages(null);if(web!=null){ServiceWorkerController.getInstance().setServiceWorkerClient(new ServiceWorkerClient(){public WebResourceResponse shouldInterceptRequest(WebResourceRequest r){return null;}});web.stopLoading();web.destroy();}super.onDestroy();}
}
